<!DOCTYPE html><html lang="de"><head><link rel="icon" href="favicon.svg" type="image/svg+xml"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rechnungsarchiv</title><link rel="stylesheet" href="styles.css"><script src="app.js" defer></script></head><body><div class="app-shell"><header class="app-header"><a class="brand" href="auftraege.php"><span class="brand-mark">CF</span><span>Computerfachmann</span></a><nav class="primary-nav"><a class="nav-link" href="auftraege.php">Reparaturaufträge</a><a class="nav-link" href="rechnungsarchiv.php" aria-current="page">Rechnungsarchiv</a><a class="nav-link" href="benutzer.php">Benutzer</a></nav></header><main><div class="page-heading"><div><p class="eyebrow">Dauerhafte Belege</p><h1>Rechnungsarchiv</h1></div></div><?php if($flash):?><div class="notice notice--<?= h($flash["typ"]) ?>"><?= h($flash["nachricht"]) ?></div><?php endif;?><form class="glass-panel toolbar archive-filter" method="get"><div class="form-field"><label for="archiv-suche">Suche</label><input id="archiv-suche" name="suche" value="<?= h($daten["suche"]) ?>" placeholder="Nummer, Kunde, Adresse, Auftrag, Geräte-Referenz"></div><div class="form-field"><label for="von">Von</label><input id="von" type="date" name="von" value="<?= h($daten["von"]) ?>"></div><div class="form-field"><label for="bis">Bis</label><input id="bis" type="date" name="bis" value="<?= h($daten["bis"]) ?>"></div><div class="form-field"><label for="archiv-status">Zahlungsstatus</label><select id="archiv-status" name="status"><option value="">Alle</option><?php foreach(["Bezahlt","Teilweise bezahlt","Offen","Storniert"] as $s):?><option <?= $daten["status"]===$s?"selected":"" ?>><?= h($s) ?></option><?php endforeach;?></select></div><button class="button button--primary">Filtern</button><a class="button button--secondary" href="rechnungsarchiv_export.php?<?= h(http_build_query($_GET)) ?>">CSV exportieren</a></form><div class="glass-panel archive-table-wrap"><table class="archive-table"><thead><tr><th>Rechnung</th><th>Kunde / Adresse</th><th>Auftrag / Geräte</th><th>Beträge</th><th>Zahlung</th><th>Aktionen</th></tr></thead><tbody><?php foreach($daten["rechnungen"] as $r):?><tr><td><strong><?= h($r["rechnungsnummer"]) ?></strong><br><?= h((new DateTimeImmutable($r["rechnungsdatum"]))->format("d.m.Y")) ?><?php if($r["storniert_am"]):?><br><span class="status-badge status--cancelled">Storniert</span><?php endif;?></td><td><?= h($r["kunde_name"]) ?><?php foreach(adresse_zeilen($r,"kunde_") as $z):?><br><?= h($z) ?><?php endforeach;?></td><td>#<?= h($r["auftragsnummer_snapshot"]) ?><br><?= h($r["geraete"]??"") ?></td><td>Netto <?= betrag_anzeigen($r["netto"]) ?><br>USt. <?= betrag_anzeigen($r["steuerbetrag"]) ?><br><strong>Brutto <?= betrag_anzeigen($r["brutto"]) ?></strong></td><td><?= h($r["zahlungsstatus"]) ?><br><?= h($r["zahlungsdatum_snapshot"]??"") ?><br><?= h($r["zahlungsart_snapshot"]??"") ?></td><td><a class="button button--secondary button--compact" href="rechnung.php?rechnung_id=<?= h($r["id"]) ?>">Anzeigen / drucken</a><?php if(!$r["storniert_am"]):?><form method="post" action="rechnung_stornieren.php" class="archive-cancel-form" onsubmit="return confirm('Möchten Sie diese Rechnung wirklich nachvollziehbar stornieren?');"><?= csrf_feld() ?><input type="hidden" name="rechnung_id" value="<?= h($r["id"]) ?>"><input name="grund" maxlength="1000" placeholder="Stornogrund" required><button class="button button--ghost-danger button--compact">Rechnung stornieren</button></form><?php endif;?></td></tr><?php endforeach;?><?php if($daten["rechnungen"]===[]):?><tr><td colspan="6">Keine Rechnungen für diesen Filter gefunden.</td></tr><?php endif;?></tbody></table></div></main></div></body></html>
